"""Explain RCU-sync scheduling, shared entry and callback decisions."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1433': ('도서관에 “정리가 끝나면 나에게 알려 주세요”라고 부탁한 순간과 실제 연락을 받은 순간은 다릅니다. 예약을 접수했다고 정리가 벌써 끝난 것은 아닙니다.', 'RCU 콜백을 예약하는 일과 나중에 실행되는 일을 구별합니다.', '콜백 예약 → 그사이에 새 updater 참여 가능 → 유예 기간 경과 → 콜백 실행을 그리세요. 예약 반환과 콜백 완료에 서로 다른 동그라미를 치세요.', ['콜백은 나중에 다른 코드가 불러 주도록 맡기는 함수입니다. rcu_sync_call은 call_rcu_hurry에 cb_head의 주소와 rcu_sync_func라는 함수 이름을 전달합니다. 앞의 것은 예약에 쓸 항목, 뒤의 것은 나중에 할 일입니다.', 'cb_head는 rcu_sync 구조체 안에 들어 있습니다. &rsp->cb_head는 rsp가 가리키는 구조체에서 그 항목의 주소를 구합니다. 함수 이름을 인자로 전달하는 것은 이 자리에서 그 함수의 본문을 직접 실행하는 것과 다릅니다.', 'call_rcu_hurry는 RCU 유예 기간을 거친 뒤 콜백을 실행하도록 맡깁니다. 유예 기간은 관련된 이전 RCU 읽기 구간들이 지나가기를 기다리는 구간입니다. hurry라는 이름도 이 기다림 규칙을 무시하고 무조건 즉시 끝내라는 뜻은 아닙니다.', '예약 함수가 돌아왔다고 콜백까지 완료됐다는 보장은 없습니다. 예약 이후 실행까지 다른 updater가 enter하거나 exit할 수 있습니다. 그래서 콜백은 실행하는 시점의 상태와 참여자 수를 다시 확인합니다.', '예약 중에는 cb_head를 포함한 구조체가 계속 유효해야 합니다. 주소만 접수해 놓고 그 메모리를 다른 용도로 바꾸면 나중에 엉뚱한 내용을 사용할 수 있습니다. 예약 반환만 보고 free하거나 같은 항목을 다른 예약용으로 함부로 재사용하면 안 됩니다.', '첫 enter의 경로에는 synchronize_rcu로 직접 기다린 뒤 rcu_sync_func를 호출하는 부분도 있습니다. 이것은 이 예약 함수의 경로와 구별하세요. 객체를 없앨 때는 활성 사용과 enter/exit 짝을 정리하고 rcu_sync_dtor 같은 종료 규약까지 지켜야 합니다.'], [('rcu_sync_call이 돌아오면 콜백까지 반드시 끝난 것일까요?', ['네. 보통 함수를 바로 호출해 끝낸 것과 같아요', '아니요. 나중에 실행할 일을 예약한 것이에요'], '이 함수는 콜백을 예약합니다. 예약 접수와 유예 기간 뒤의 실행은 다른 사건이므로 반환만으로 완료를 판단하면 안 됩니다.'), ('예약된 콜백이 쓸 구조체는 어떻게 관리해야 할까요?', ['콜백 완료와 필요한 종료 정리까지 유효하게 유지해요', '예약 함수가 돌아오는 즉시 free해요'], 'cb_head가 구조체 안에 있고 콜백은 그 구조체에 접근합니다. 바로 메모리를 반납하면 아직 남은 작업이 사라진 객체를 쓸 수 있습니다. 다른 활성 사용도 끝났는지 함께 확인해야 합니다.')]), 'os1434': ('지름길을 닫는 표지판을 세워도 이미 그 길에 들어간 사람은 남아 있습니다. 안내판을 바꾼 뒤 이전 통행이 지나가기를 기다리는 두 단계가 필요합니다.', '첫 enter의 짧은 상태 변경과 잠금 밖에서 하는 긴 대기를 구별합니다.', 'IDLE·0 → 잠금 안에서 ENTER·1 → 잠금 해제 → synchronize_rcu 대기 → PASSED·1을 적으세요. 이 예시는 첫 참여자가 아직 exit하지 않은 경우입니다.', ['처음에는 GP_IDLE이라 reader가 빠른 길을 쓸 수 있습니다. updater가 rcu_sync_enter를 부르면 rss_lock이라는 내부 잠금을 잡고 현재 단계를 지역 변수 gp_state에 기억합니다. 지역 변수는 이번 호출이 출발한 단계를 기억하는 메모입니다.', '출발 단계가 IDLE이면 공유 상태를 GP_ENTER로 바꿉니다. ENTER는 빠른 길을 닫는 전환이 시작됐다는 표시입니다. 이어 gp_count를 하나 늘려 아직 exit하지 않은 참여자 한 명을 기록합니다. 이 두 변경은 내부 잠금으로 보호합니다.', '그다음 spin_unlock_irq로 내부 잠금을 풉니다. 이후 synchronize_rcu를 호출해 필요한 유예 기간을 기다립니다. 오래 걸릴 수 있는 기다림 전체를 이 짧은 spinlock 안에서 하는 것은 아닙니다.', '왜 ENTER를 적자마자 돌아가지 않을까요? 이전에 빠른 길 허용을 보고 진행하던 RCU 읽기 구간과 순서를 맞춰야 하기 때문입니다. 표지판을 바꾼 순간과 이전 통행이 지나갔음을 확인한 순간은 다릅니다.', '유예 기간 뒤에는 rcu_sync_func를 직접 호출합니다. 정상적인 첫 진입에서는 자신의 gp_count가 아직 남아 있으므로 이 함수가 GP_PASSED로 바꾸고 진입 대기자들을 깨웁니다. PASSED는 진입 전환을 통과했다는 뜻이며 빠른 길을 다시 열었다는 뜻이 아닙니다.', 'enter가 끝난 뒤 updater는 상위 잠금의 규칙에 맞게 일을 이어 갑니다. percpu rwsem에서는 다른 writer와의 배제와 기존 reader 종료 확인이 더 필요합니다. 이 RCU 전환 한 단계가 모든 자료 접근의 독점권까지 주지는 않습니다. 참여를 끝내면 대응하는 exit가 필요합니다.'], [('첫 enter가 synchronize_rcu로 기다릴 때 내부 rss_lock은?', ['전체 유예 기간 동안 계속 잡고 있어요', '이미 풀어 둔 상태예요'], '원문은 gp_count를 늘린 뒤 spin_unlock_irq를 하고 나서 synchronize_rcu를 부릅니다. 짧은 상태 변경을 보호하는 잠금을 긴 기다림 전체에 걸쳐 잡는다는 설명은 틀립니다.'), ('첫 enter의 유예 기간을 마치고 아직 exit하지 않았다면 어떤 단계일까요?', ['GP_PASSED예요', '빠른 길이 다시 열린 GP_IDLE이에요'], '자신의 참여 수가 남아 있어 콜백 처리가 PASSED로 바꿉니다. 빠른 길 복귀는 뒤의 exit와 종료 전환이 필요하므로 여기서 IDLE로 읽으면 안 됩니다.')]), 'os1435': ('앞사람이 이미 지름길을 닫는 절차를 진행 중이면 뒷사람도 그 절차에 함께 참여할 수 있습니다. 참여할 때마다 같은 준비를 처음부터 다시 할 필요는 없습니다.', '여러 updater가 읽기 경로 전환을 공유하는 이유와 그 한계를 배웁니다.', 'A: ENTER·1 → B 참여: ENTER·2 → 유예 기간 완료: PASSED·2를 쓰세요. 별도로 PASSED에서 C 참여 시 count만 하나 늘리고 조건이 이미 맞는 경우를 적으세요.', ['첫 updater A가 IDLE을 ENTER로 바꾸고 유예 기간을 기다리는 동안 B도 enter할 수 있습니다. B는 내부 잠금 아래 gp_count를 늘립니다. A와 B 두 명이 참여하면 수는 2가 되지만 전환 단계는 아직 ENTER일 수 있습니다.', '출발 때 IDLE이 아니었던 B는 첫 진입의 synchronize_rcu 분기로 가지 않습니다. 대신 wait_event로 gp_state가 GP_PASSED 이상인지 확인합니다. wait_event는 조건이 맞으면 진행하고, 아니면 조건을 기다리는 도구입니다.', '코드의 단계 번호는 IDLE=0, ENTER=1, PASSED=2, EXIT=3, REPLAY=4입니다. >=는 크거나 같은지 묻습니다. ENTER의 1은 2보다 작아 기다리고, PASSED의 2는 조건을 만족합니다. 이 비교는 이 코드가 정한 단계 번호 순서에 근거합니다.', 'A의 유예 기간이 끝나 상태가 PASSED가 되고 대기자가 깨어나면 B도 진행할 수 있습니다. 이미 PASSED인 동안 새로 참여했다면 조건이 처음부터 맞습니다. EXIT나 REPLAY도 숫자 비교를 만족하므로 기존 전환을 이용할 수 있습니다.', '이렇게 가까운 시점의 enter들은 빠른 읽기 길을 닫아 둔 상태를 공유합니다. 매번 독립된 새 유예 기간을 반드시 기다리는 것보다 준비 비용을 줄일 수 있습니다. 그래도 참여 수를 늘렸다면 각 참여에 대응하는 exit를 정확히 한 번 해야 합니다.', 'gp_count=2는 두 updater가 같은 자료를 동시에 마음대로 고쳐도 된다는 허가가 아닙니다. rcu_sync는 읽기 경로 전환을 조정합니다. writer끼리 한 명씩 들어가게 하는 규칙은 별도로 필요하며, percpu rwsem은 block이라는 차단 표시로 그 일을 합니다.'], [('이미 PASSED일 때 두 번째 enter도 반드시 새 유예 기간을 처음부터 기다릴까요?', ['네. 참여할 때마다 무조건 새 synchronize_rcu를 호출해요', '아니요. 이미 이루어진 전환을 공유할 수 있어요'], 'IDLE이 아닌 경로는 상태 조건을 봅니다. 이미 PASSED 이상이면 조건이 맞으므로 매번 새 synchronize_rcu를 호출한다는 답은 틀립니다.'), ('rcu_sync_enter만 있으면 writer끼리의 동시 수정도 자동으로 막을까요?', ['아니요. 자료 쓰기의 독점 규칙은 따로 필요해요', '네. gp_count가 증가하면 자동으로 한 명만 수정해요'], '여러 updater가 전환에 함께 참여하도록 수를 세는 구조입니다. 수를 세는 것만으로 한 명만 고르게 되지는 않습니다. percpu rwsem의 block처럼 별도 배제 장치가 필요합니다.')]), 'os1436': ('안내원이 “모두 나갔으니 나중에 문을 열자”고 예약했는데 그사이에 새 공사팀이 왔습니다. 예약 당시만 기억하지 말고 실제 문을 열 때 누가 남았는지 다시 봐야 합니다.', '콜백이 현재 참여자 수를 먼저 확인하고 빠른 길을 유지하거나 닫는 이유를 이해합니다.', 'EXIT·0에서 콜백 예약 → 새 enter로 EXIT·1 → 콜백 실행 → PASSED·1을 적으세요. 마지막에도 빠른 읽기 길은 닫혀 있다고 표시하세요.', ['rcu_sync_func가 받는 rhp는 구조체 전체의 주소가 아니라 그 안의 cb_head 항목을 가리킵니다. container_of는 이 항목이 rcu_sync 안의 어디에 있는지 이용해 전체 구조체 주소를 찾습니다. 상자 속 칸의 위치를 알고 상자 시작을 찾는 셈입니다.', '임의의 주소에서 아무 부모나 찾는 마법은 아닙니다. rhp가 실제 rcu_sync의 cb_head를 가리키고 그 객체가 살아 있어야 합니다. 여기서 찾는 대상은 대기자의 task_struct가 아니라 RCU 전환을 관리하는 rcu_sync입니다.', '먼저 IDLE이나 PASSED에서 예상 밖으로 호출됐는지 WARN_ON_ONCE로 검사합니다. 이 경고가 상태를 정상 값으로 고쳐 주는 것은 아닙니다. 이어 spin_lock_irqsave로 내부 상태를 보호하고 인터럽트 상태를 저장합니다.', '잠금 안에서는 gp_count가 남아 있는지를 먼저 봅니다. 정상적인 사용에서 1 이상이면 아직 updater가 있으므로 GP_PASSED를 저장하고 wake_up_locked로 진입을 기다리는 작업에게 알려 줍니다. 깨웠다고 reader의 빠른 길을 여는 것은 아닙니다. 빠른 길은 IDLE에서만 허용됩니다.', '예를 들어 EXIT·0에서 종료 콜백을 예약한 뒤 B가 들어와 count가 1이 되었다고 합시다. 콜백은 현재의 1을 보므로 IDLE로 열지 않고 PASSED로 갑니다. 예약 당시 0이었다는 이유로 문을 열면 새 updater가 필요한 전환을 잃게 됩니다.', 'count가 0일 때에만 그다음 REPLAY 여부와 IDLE 복귀 분기를 살핍니다. 따라서 검사 순서가 중요합니다. 상태 변경 뒤에는 spin_unlock_irqrestore로 내부 잠금을 풀고 이전 인터럽트 상태를 복원합니다. 콜백 한 번이 항상 같은 결과를 내는 것이 아니라 현재 조건에 따라 갈립니다.'], [('EXIT에서 예약한 콜백이 실행될 때 새 updater가 있어 count=1이면?', ['처음 예약 때 0이었으니 무조건 IDLE로 가요', 'PASSED로 가서 빠른 읽기 길을 계속 닫아 둬요'], '콜백은 현재 gp_count를 먼저 확인합니다. 참여자가 남아 있으면 PASSED로 가므로, 예약 때의 값만 믿고 IDLE로 여는 답은 틀립니다.'), ('container_of(rhp, struct rcu_sync, cb_head)는 무엇을 찾을까요?', ['cb_head를 포함하는 rcu_sync 구조체예요', '아무 대기자의 task_struct예요'], '형식 이름과 멤버 이름이 rcu_sync와 cb_head로 지정되어 있습니다. 해당 멤버 주소로 그 구조체의 시작을 찾는 것이며 임의의 작업 구조체를 찾는 연산이 아닙니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_354.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
